CREATE FUNCTION pg_temp.t(d integer,tm text) RETURNS timestamptz LANGUAGE sql STABLE AS $$
 SELECT (((statement_timestamp() AT TIME ZONE 'UTC')::date+d)+tm::time) AT TIME ZONE 'UTC' $$;
