 'allocations',(SELECT jsonb_agg(to_jsonb(a)) FROM public.hotel_room_allocations a WHERE a.capacity_reservation_id='20000000-0000-4000-8000-000000000006'),
 'audits',(SELECT jsonb_agg(to_jsonb(e)) FROM public.entity_audit_events e),
 'rooms',jsonb_build_array(jsonb_build_object('roomId','20000000-0000-4000-8000-000000000003','roomName','Synthetic Room','roomTypeId','20000000-0000-4000-8000-000000000002')))
INTO payload FROM public.hotel_stays s WHERE s.id='20000000-0000-4000-8000-000000000004';
result:=public.hotel_history_individual_010(payload);
IF jsonb_array_length(result->'segments') IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'history compatibility: %',result; END IF;
PERFORM pg_temp.assert_true((result->'segments'->0->>'usedFrom')::timestamptz=pg_temp.t(-2,'00:51'),'actual historical start');
